def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # If no keys are provided, return all values
    if not keys:
        return list(self._values)

    result = []
    for key in keys:
        if isinstance(key, int):
            # Treat as index
            try:
                result.append(self._values[key])
            except IndexError:
                raise IndexError(f"Index {key} out of range")
        else:
            # Treat as key
            try:
                idx = self._keys.index(key)
                result.append(self._values[idx])
            except ValueError:
                raise KeyError(f"Key {key} not found")
    return result

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key.
    Keys provided in the items that are not in the record will be
    inserted with a value of None; indexes provided that are out of
    bounds will trigger an IndexError.
    """
    # If no keys are specified, return all key/value pairs
    if not keys:
        return {k: self._data.get(k) for k in self._keys}

    result = {}
    for key in keys:
        if isinstance(key, int):
            # Index access
            if key < 0 or key >= len(self._keys):
                raise IndexError(f"Index {key} out of bounds")
            k = self._keys[key]
            result[k] = self._data.get(k)
        else:
            # Key access
            if key in self._data:
                result[key] = self._data[key]
            else:
                result[key] = None
    return result

